def solve(s: str) -> bool:
    """Validate an IPv4 address.
    The address must consist of exactly four decimal numbers separated by dots.
    Each number is in the range 0-255, has no leading zeros unless the number
    itself is 0, and contains only digits. No extra whitespace is allowed.
    """
    # Quick check: must be a non‑empty string without surrounding whitespace.
    if not isinstance(s, str) or not s:
        return False
    # IPv4 should not contain any spaces.
    if ' ' in s:
        return False
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        # Each part must be non‑empty and consist only of digits.
        if not part.isdigit():
            return False
        # No leading zeros unless the part is exactly "0".
        if len(part) > 1 and part[0] == '0':
            return False
        # Value must be within 0‑255.
        if int(part) > 255:
            return False
    return True

