def solve(s: str) -> bool:
    """Validate an IPv4 address.
    The address must consist of exactly four decimal numbers separated by dots.
    Each number is in the range 0-255, has no leading zeros unless the number
    itself is 0, and contains only digits. Leading/trailing whitespace is ignored.
    """
    if not isinstance(s, str):
        return False
    # Strip leading/trailing whitespace but reject internal spaces.
    s = s.strip()
    # Quick reject if any whitespace remains inside.
    if any(ch.isspace() for ch in s):
        return False
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part:
            return False
        if not part.isdigit():
            return False
        # No leading zeros unless the part is exactly "0"
        if len(part) > 1 and part[0] == '0':
            return False
        val = int(part)
        if val < 0 or val > 255:
            return False
    return True

