def solve(n: int, edges: list) -> int:
    if n <= 0:
        return -1
    adj = [[] for _ in range(n)]
    for e in edges:
        a, b, w = e[0], e[1], e[2]
        adj[a].append((b, w))
        adj[b].append((a, w))
    dist = [None] * n
    dist[0] = 0
    heap = [(0, 0)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        if u == n - 1:
            return d
        for v, w in adj[u]:
            nd = d + w
            if dist[v] is None or nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
