from collections import deque

def solve(grid: list) -> int:
    if not grid or not grid[0]:
        return -1
    rows, cols = len(grid), len(grid[0])
    if grid[0][0] in (1, '1') or grid[rows - 1][cols - 1] in (1, '1'):
        return -1
    seen = {(0, 0)}
    queue = deque([(0, 0, 0)])
    while queue:
        r, c, d = queue.popleft()
        if r == rows - 1 and c == cols - 1:
            return d
        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dx, c + dy
            if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in seen and grid[nr][nc] not in (1, '1'):
                seen.add((nr, nc))
                queue.append((nr, nc, d + 1))
    return -1

